<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Sorting Algorithm Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #10131c;
      --panel: #1b2030;
      --bar: #6c8cff;
      --active: #ffb454;
      --sorted: #46d39a;
      --text: #e8ebf5;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background: radial-gradient(circle at top, #202944, var(--bg) 60%);
      color: var(--text);
      font: 16px system-ui, sans-serif;
    }

    main {
      width: min(920px, calc(100vw - 32px));
      padding: 28px;
      border: 1px solid #333b55;
      border-radius: 18px;
      background: rgba(27, 32, 48, .94);
      box-shadow: 0 20px 60px #0008;
    }

    h1 { margin: 0 0 8px; font-size: 1.5rem; }
    p { margin: 0 0 22px; color: #aeb8d3; }

    #bars {
      height: 330px;
      display: flex;
      align-items: end;
      gap: 5px;
      padding: 16px;
      overflow: hidden;
      border-radius: 12px;
      background: #0c1019;
      border: 1px solid #303851;
    }

    .bar {
      flex: 1 1 0;
      min-width: 3px;
      background: linear-gradient(to top, #4d6de5, var(--bar));
      border-radius: 4px 4px 0 0;
      transition: height .12s ease, background .12s ease;
    }

    .bar.active {
      background: linear-gradient(to top, #e68e36, var(--active));
    }

    .bar.done {
      background: linear-gradient(to top, #239d6a, var(--sorted));
    }

    .controls {
      display: flex;
      gap: 10px;
      margin-top: 20px;
    }

    button {
      border: 0;
      border-radius: 9px;
      padding: 10px 16px;
      color: var(--text);
      background: #303b5d;
      font: inherit;
      font-weight: 650;
      cursor: pointer;
    }

    button:hover { background: #43517b; }
    button:disabled { opacity: .55; cursor: wait; }
  </style>
</head>
<body>
  <main>
    <h1>Sorting Visualizer</h1>
    <p>Bubble sort, one comparison at a time.</p>
    <div id="bars" aria-label="Array bars"></div>
    <div class="controls">
      <button id="sort">Sort</button>
      <button id="shuffle">Shuffle</button>
      <button id="reset">Reset</button>
    </div>
  </main>

  <script>
    (() => {
      const bars = document.getElementById("bars");
      const sortButton = document.getElementById("sort");
      const shuffleButton = document.getElementById("shuffle");
      const resetButton = document.getElementById("reset");

      let values = [42, 12, 68, 25, 91, 36, 77, 8, 54, 18, 83, 30, 62, 47, 70, 22];
      const initial = values.slice();
      let index = 0;
      let end = values.length - 1;
      let active = [];
      let running = false;

      function isSorted() {
        return values.every((value, i) => i === 0 || values[i - 1] <= value);
      }

      function resetSortState() {
        index = 0;
        end = values.length - 1;
        active = [];
      }

      function draw() {
        const maximum = Math.max(...values, 1);
        bars.replaceChildren(...values.map((value, i) => {
          const bar = document.createElement("div");
          bar.className = "bar";
          if (active.includes(i)) bar.classList.add("active");
          if (end < i) bar.classList.add("done");
          bar.style.height = `${Math.max(3, (value / maximum) * 100)}%`;
          bar.title = String(value);
          return bar;
        }));
      }

      function sortStep() {
        if (values.length < 2 || isSorted()) {
          active = [];
          draw();
          return true;
        }

        active = [index, index + 1];
        if (values[index] > values[index + 1]) {
          [values[index], values[index + 1]] = [values[index + 1], values[index]];
        }

        index++;
        if (index >= end) {
          end--;
          index = 0;
        }

        const complete = isSorted();
        if (complete) active = [];
        draw();
        return complete;
      }

      function setArray(array) {
        values = Array.from(array, Number);
        resetSortState();
        draw();
      }

      function shuffle() {
        for (let i = values.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [values[i], values[j]] = [values[j], values[i]];
        }
        resetSortState();
        draw();
      }

      function setControlsDisabled(disabled) {
        sortButton.disabled = disabled;
        shuffleButton.disabled = disabled;
        resetButton.disabled = disabled;
      }

      sortButton.addEventListener("click", () => {
        if (running) return;
        running = true;
        setControlsDisabled(true);

        const animate = () => {
          if (sortStep()) {
            running = false;
            setControlsDisabled(false);
            return;
          }
          setTimeout(animate, 45);
        };
        animate();
      });

      shuffleButton.addEventListener("click", shuffle);
      resetButton.addEventListener("click", () => setArray(initial));

      window.viz = {
        array: () => values.slice(),
        setArray,
        sortStep,
        sorted: isSorted
      };

      draw();
    })();
  </script>
</body>
</html>
